MAX_LENGTH = 200


def shorten(line):
    """Limit notification length in Unicode characters, not encoded bytes."""
    return line[:MAX_LENGTH]


def message(args):
    """Build Unicode notification text, preserving names in all languages."""
    body = args.get("text", "")
    who = args.get("mention")
    line = "%s: %s" % (who, body) if who else body
    return shorten(line)
